import type { ReactNode } from 'react';
import { Link } from '@tanstack/react-router';
import { GAME_APP_ICON_SRC } from '~/components/GameAppIcon';
import { cn } from '~/lib/utils';
import type { GameKind } from '~/util/catalog/tags';
import { gameKindLabel } from '~/util/games/labels';
import { simpleGameEditHref } from '~/util/games/kinds';

/** Unpadded 128px marks, generated by `src/images/icon/make.imgs.sh`. */
const GAME_KIND_ICON_SRC = {
  ...GAME_APP_ICON_SRC,
  dvayi: '/img/dvayi_icons/icon_128_no_pad.png',
  bhramita: '/img/bhramita_icons/icon_128_no_pad.png',
  surupa: '/img/surupa_icons/icon_128_no_pad.png',
  anveshi: '/img/anveshi_icons/icon_128_no_pad.png'
} as const satisfies Record<GameKind, string>;

export { gameKindLabel };

/** The game's own mark (its app icon). */
export function GameKindIcon({ game, className }: { game: GameKind; className?: string }) {
  return (
    <img
      src={GAME_KIND_ICON_SRC[game]}
      alt=""
      title={gameKindLabel(game)}
      className={cn('size-5 shrink-0 rounded-[4px] object-contain', className)}
    />
  );
}

/** Admin editor for a listed puzzle — always opens in a new tab. */
export function PuzzleEditLink({
  game,
  id,
  className,
  children
}: {
  game: GameKind;
  id: number;
  className?: string;
  children: ReactNode;
}) {
  const shared = {
    target: '_blank' as const,
    rel: 'noopener noreferrer',
    className
  };
  if (game === 'padavali') {
    return (
      <Link to="/padavali/edit/$id" params={{ id: String(id) }} {...shared}>
        {children}
      </Link>
    );
  }
  if (game === 'padajala') {
    return (
      <Link to="/padajala/edit/$id" params={{ id: String(id) }} {...shared}>
        {children}
      </Link>
    );
  }
  return (
    <a href={simpleGameEditHref(game, id)} {...shared}>
      {children}
    </a>
  );
}
